436	/** The stored claims, kept per sheet. Ids are assigned in the order claims are added. */
437	@Repository
438	public class ClaimRepository {
439	
440	    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, due, opened_by, stated, stated_due";
441	
442	    private final JdbcTemplate jdbc;
443	    private final DataSource dataSource;
444	
445	    public ClaimRepository(JdbcTemplate jdbc, DataSource dataSource) {
446	        this.jdbc = jdbc;
447	        this.dataSource = dataSource;
448	    }
449	
450	    /** The sheet's claims, newest first. */
451	    public List<Claim> list(String sheetId) {
452	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY id DESC",
453	                ClaimRepository::map, sheetId);
454	    }
455	
456	    public Claim find(String sheetId, long id) {
457	        List<Claim> found = jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?",
458	                ClaimRepository::map, sheetId, id);
459	        return found.isEmpty() ? null : found.get(0);
460	    }
461	
462	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note) {
463	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
464	        jdbc.update(con -> {
465	            PreparedStatement ps = con.prepareStatement(
466	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note) VALUES (?, ?, ?, ?, ?)",
467	                    new String[] { "id" });
468	            ps.setString(1, sheetId);
469	            ps.setLong(2, personId);
470	            ps.setBigDecimal(3, amount);
471	            ps.setDate(4, Date.valueOf(date));
472	            ps.setString(5, note);
473	            return ps;
474	        }, keys);
475	        return new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null, false, null);
476	    }
477	
478	    public void update(Claim claim) {
479	        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ? WHERE sheet_id = ? AND id = ?",
480	                claim.amount(), Date.valueOf(claim.date()), claim.note(), claim.sheetId(), claim.id());
481	    }
482	
483	    /**
484	     * Stores the claim's status, number, fixed due and who opened it, but only while its status is still {@code from}; false when another
485	     * change got there first (nothing is written).
486	     */
487	    public boolean updateStatus(Claim claim, ClaimStatus from) {
488	        return jdbc.update("UPDATE claim SET status = ?, claim_number = ?, due = ?, opened_by = ? WHERE sheet_id = ? AND id = ? AND status = ?",
489	                claim.status().name(), claim.number(), claim.due(), claim.openedBy(), claim.sheetId(), claim.id(), from.name()) == 1;
490	    }
491	
492	    /** Binds the claim to a statement figure (null: it had none), or unbinds it when {@code stated} is false. */
493	    public void bind(Claim claim, boolean stated, BigDecimal statedDue) {
494	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
495	                stated, stated ? statedDue : null, claim.sheetId(), claim.id());
496	    }
497	
498	    /**
499	     * The sheet's next claim number: 1 for the first, then one more each time. The sheet's counter row stays locked
500	     * until the transaction ends, so two claims opened at once get different numbers, and a rolled back opening gives
501	     * its number back.
502	     */
503	    public long nextNumber(String sheetId) {
504	        ensureNumberRow(sheetId);
505	        jdbc.update("UPDATE claim_number_seq SET last_number = last_number + 1 WHERE sheet_id = ?", sheetId);
506	        return jdbc.queryForObject("SELECT last_number FROM claim_number_seq WHERE sheet_id = ?", Long.class, sheetId);
507	    }
508	
509	    /**
510	     * Adds the sheet's counter row if it has none, on its own connection so the row is committed at once and two
511	     * openings at the same moment never both try to add it.
512	     */
513	    private synchronized void ensureNumberRow(String sheetId) {
514	        try (Connection con = dataSource.getConnection()) {
515	            con.setAutoCommit(true);
516	            try (PreparedStatement ps = con.prepareStatement("INSERT INTO claim_number_seq (sheet_id, last_number) "
517	                    + "SELECT ?, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM claim_number_seq WHERE sheet_id = ?)")) {
518	                ps.setString(1, sheetId);
519	                ps.setString(2, sheetId);
520	                ps.executeUpdate();
521	            }
522	        } catch (SQLException e) {
523	            throw new IllegalStateException(e);
524	        }
525	    }
526	
527	    private static Claim map(ResultSet rs, int n) throws SQLException {
528	        BigDecimal due = rs.getBigDecimal("due");
529	        BigDecimal statedDue = rs.getBigDecimal("stated_due");
530	        return new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
531	                rs.getBigDecimal("amount").setScale(2), rs.getObject("claim_date", LocalDate.class),
532	                rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
533	                rs.getObject("claim_number", Long.class), due == null ? null : due.setScale(2),
534	                rs.getString("opened_by"), rs.getBoolean("stated"), statedDue == null ? null : statedDue.setScale(2));
535	    }
536	}
