552	package net.officefloor.hq.app.rollup;
553	
554	import java.math.BigDecimal;
555	import java.time.LocalDate;
556	import java.util.LinkedHashMap;
557	import java.util.List;
558	import java.util.Map;
559	import java.util.Objects;
560	import net.officefloor.hq.app.Audit;
561	import net.officefloor.hq.app.claim.Claim;
562	import net.officefloor.hq.app.claim.ClaimDue;
563	import net.officefloor.hq.app.claim.ClaimRepository;
564	import net.officefloor.hq.app.person.Person;
565	import net.officefloor.hq.app.person.PersonRepository;
566	import net.officefloor.hq.app.rate.RateRepository;
567	import net.officefloor.hq.app.sheet.SheetRepository;
568	import org.springframework.stereotype.Service;
569	
570	/**
571	 * The sheet's figures as the screen shows them: each person's claimed (their claims that count added up) and
572	 * due-total (the figures of those claims added up; n/a when their grade has no rate today and no counting claim
573	 * keeps a figure), and the sheet's claimed-total and due-total (everyone's added up, skipping n/a).
574	 *
575	 * A change takes the figures before it ({@link #take}) and, after its own audit lines, writes ROLLUP for every
576	 * person whose figures moved (a person new to the sheet counts as moved), then TOTALS when the sheet's totals
577	 * moved ({@link #record}).
578	 */
579	@Service
580	public class Rollup {
581	
582	    private final PersonRepository people;
583	    private final ClaimRepository claims;
584	    private final RateRepository rates;
585	    private final SheetRepository sheets;
586	    private final Audit audit;
587	
588	    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
589	            Audit audit) {
590	        this.people = people;
591	        this.claims = claims;
592	        this.rates = rates;
593	        this.sheets = sheets;
594	        this.audit = audit;
595	    }
596	
597	    /** Every person's figures on the sheet now, in the order they were added. */
598	    public RollupBefore take(String sheetId) {
599	        LocalDate today = sheets.today(sheetId);
600	        List<Claim> all = claims.list(sheetId);
601	        Map<Long, Figures> figures = new LinkedHashMap<>();
602	        for (Person person : people.list(sheetId)) {
603	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
604	            BigDecimal due = BigDecimal.ZERO.setScale(2);
605	            boolean kept = false;
606	            for (Claim c : all) {
607	                if (c.personId() != person.id() || !ClaimDue.counts(c)) {
608	                    continue;
609	                }
610	                claimed = claimed.add(c.amount());
611	                kept |= ClaimDue.kept(c);
612	                BigDecimal figure = ClaimDue.figure(c, person.grade(), rates);
613	                if (figure != null) {
614	                    due = due.add(figure);
615	                }
616	            }
617	            String dueTotal = rates.find(sheetId, person.grade(), today) == null && !kept ? "n/a"
618	                    : due.toPlainString();
619	            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), dueTotal));
620	        }
621	        return new RollupBefore(figures);
622	    }
623	
624	    /** Writes the ROLLUP and TOTALS lines for the figures the change moved since {@code before}. */
625	    public void record(String sheetId, String by, RollupBefore before) {
626	        Map<Long, Figures> after = take(sheetId).figures();
627	        for (Map.Entry<Long, Figures> e : after.entrySet()) {
628	            Figures was = before.figures().get(e.getKey());
629	            Figures now = e.getValue();
630	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
631	                audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
632	                        + now.claimed() + " due-total=" + now.dueTotal());
633	            }
634	        }
635	        String claimedBefore = claimedTotal(before.figures());
636	        String dueBefore = dueTotal(before.figures());
637	        String claimedAfter = claimedTotal(after);
638	        String dueAfter = dueTotal(after);
639	        if (!Objects.equals(claimedBefore, claimedAfter) || !Objects.equals(dueBefore, dueAfter)) {
640	            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + claimedAfter + " due-total="
641	                    + dueAfter);
642	        }
643	    }
644	
645	    private static String claimedTotal(Map<Long, Figures> figures) {
646	        return figures.values().stream().map((f) -> new BigDecimal(f.claimed()))
647	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
648	    }
649	
650	    private static String dueTotal(Map<Long, Figures> figures) {
651	        return figures.values().stream().filter((f) -> !f.dueTotal().equals("n/a"))
652	                .map((f) -> new BigDecimal(f.dueTotal())).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add)
653	                .toPlainString();
654	    }
655	}
