671	import java.io.IOException;
672	import java.io.UncheckedIOException;
673	import java.nio.charset.StandardCharsets;
674	import java.nio.file.Files;
675	import java.nio.file.Path;
676	import java.nio.file.StandardOpenOption;
677	import org.springframework.beans.factory.annotation.Value;
678	import org.springframework.stereotype.Service;
679	
680	/**
681	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
682	 * so tests can assert side-effects by reading that file — the second test-assertion channel
683	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
684	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
685	 *
686	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
687	 * SYNC) so a test reads the record immediately.
688	 */
689	@Service
690	public class Audit {
691	
692	    private final Path file;
693	
694	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
695	        this.file = Path.of(path);
696	    }
697	
698	    /** Append one audit record. Tests assert the exact line(s) in the file. */
699	    public synchronized void record(String entry) {
700	        try {
701	            Path parent = file.toAbsolutePath().getParent();
702	            if (parent != null) {
703	                Files.createDirectories(parent);
704	            }
705	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
706	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
707	        } catch (IOException e) {
708	            throw new UncheckedIOException(e);
709	        }
710	    }
711	
712	    /** Remove the audit file. */
713	    public synchronized void clear() {
714	        try {
715	            Files.deleteIfExists(file);
716	        } catch (IOException e) {
717	            throw new UncheckedIOException(e);
718	        }
719	    }
720	}
